function loadAt(date) {
    const h = date.getHours() + date.getMinutes() / 60;
    // Diurnal residential load: morning + evening peaks, midday plateau.
    if (h >= 6 && h <= 9)   return 1.8;
    if (h >= 17 && h <= 22) return 2.4;
    if (h >= 0 && h <= 5)   return 0.6;
    return 1.2;
}
const meterId = (msg.req && msg.req.params && msg.req.params.meter_id) || 'meter-unknown';
const readings = [];
const now = Date.now();
for (let i = 23; i >= 0; i--) {
    const t = new Date(now - i * 3600_000);
    const kw = loadAt(t);
    const w_per_phase = Math.round((kw * 1000) / 3);
    readings.push({
        timestamp: t.toISOString(),
        active_power_l1_w: w_per_phase,
        active_power_l2_w: w_per_phase,
        active_power_l3_w: w_per_phase,
        voltage_l1_v: 230, voltage_l2_v: 230, voltage_l3_v: 230,
        current_l1_a: w_per_phase / 230, current_l2_a: w_per_phase / 230, current_l3_a: w_per_phase / 230,
        power_factor: 0.95,
        frequency_hz: 50,
        total_energy_kwh: kw * (24 - i)  // monotonic across the window
    });
}
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
msg.payload = { meter_id: meterId, readings };
return msg;

function pvAt(date) {
    const h = date.getHours() + date.getMinutes() / 60;
    // Solar bell curve, peak at noon. Zero at night.
    if (h < 6 || h > 19) return { power_kw: 0, irradiance: 0 };
    const peakOffset = Math.abs(h - 12.5) / 6.5;
    const factor = Math.max(0, 1 - Math.pow(peakOffset, 2));
    return { power_kw: Math.round(factor * 5 * 100) / 100, irradiance: Math.round(factor * 850) };
}
const systemId = (msg.req && msg.req.params && msg.req.params.system_id) || 'pv-unknown';
const readings = [];
const now = Date.now();
for (let i = 23; i >= 0; i--) {
    const t = new Date(now - i * 3600_000);
    const p = pvAt(t);
    readings.push({
        timestamp: t.toISOString(),
        power_kw: p.power_kw,
        irradiance_w_m2: p.irradiance,
        panel_temp_c: Math.round(20 + (p.power_kw / 5) * 25),
        efficiency: 0.18
    });
}
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
msg.payload = { system_id: systemId, readings };
return msg;

function weatherAt(date) {
    const h = date.getHours();
    // Mid-latitude diurnal: cool nights, warm afternoons.
    const tempBase = 12 + 8 * Math.sin((h - 8) / 24 * Math.PI * 2);
    const cloud = h >= 4 && h <= 7 ? 70 : h >= 18 && h <= 21 ? 40 : 25;
    return {
        temperature_c: Math.round(tempBase * 10) / 10,
        humidity_percent: Math.round(60 + 20 * Math.cos((h - 4) / 24 * Math.PI * 2)),
        wind_speed_ms: 2 + Math.abs(Math.sin(h)) * 3,
        cloud_cover_percent: cloud,
        ghi_w_m2: h >= 6 && h <= 19 ? Math.round(800 * (1 - Math.abs(h - 12.5) / 6.5)) : 0
    };
}
const stationId = (msg.req && msg.req.params && msg.req.params.station_id) || 'station-unknown';
const readings = [];
const now = Date.now();
for (let i = 23; i >= 0; i--) {
    const t = new Date(now - i * 3600_000);
    readings.push({ timestamp: t.toISOString(), ...weatherAt(t) });
}
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
msg.payload = { station_id: stationId, readings };
return msg;

// Synthesised analytics aggregates. Real implementations would query Trino's
// silver/gold layer for the requested metric and range, then run computeTrends/
// detectAnomalies/computeCorrelations/generateRecommendations server-side.
const action = msg._req && msg._req.action;
const payload = (msg._req && msg._req.payload) || {};
const now = new Date();

function sample(generator, hours) {
    const out = [];
    const t0 = Date.now();
    for (let i = hours - 1; i >= 0; i--) {
        const t = new Date(t0 - i * 3600_000);
        out.push({ timestamp: t.toISOString(), value: generator(t) });
    }
    return out;
}
function loadAt(d) { const h = d.getHours(); return h >= 6 && h <= 22 ? 1.8 + Math.sin(h) * 0.4 : 0.6; }
function pvAt(d) { const h = d.getHours() + d.getMinutes() / 60; if (h < 6 || h > 19) return 0; return Math.max(0, 1 - Math.pow(Math.abs(h - 12.5) / 6.5, 2)) * 5; }

if (action === 'analytics.trends') {
    const metric = payload.metric || 'meter.power_kw';
    const range = Number(payload.range) || 24;
    const gen = metric.startsWith('pv') ? pvAt : loadAt;
    const series = sample(gen, range);
    const values = series.map(s => s.value);
    const min = Math.min(...values);
    const max = Math.max(...values);
    const avg = values.reduce((a, b) => a + b, 0) / values.length;
    const trend = values[values.length - 1] > values[0] ? 'up' : values[values.length - 1] < values[0] ? 'down' : 'stable';
    msg._result = { ok: true, data: { metric, range, series, min, max, avg, trend, generated_at: now.toISOString() } };
    return msg;
}

if (action === 'analytics.correlations') {
    const metricA = payload.metricA || 'meter.power_kw';
    const metricB = payload.metricB || 'pv.power_kw';
    const a = sample(metricA.startsWith('pv') ? pvAt : loadAt, 24).map(p => p.value);
    const b = sample(metricB.startsWith('pv') ? pvAt : loadAt, 24).map(p => p.value);
    const meanA = a.reduce((s, v) => s + v, 0) / a.length;
    const meanB = b.reduce((s, v) => s + v, 0) / b.length;
    let num = 0, denA = 0, denB = 0;
    for (let i = 0; i < a.length; i++) {
        num += (a[i] - meanA) * (b[i] - meanB);
        denA += (a[i] - meanA) ** 2;
        denB += (b[i] - meanB) ** 2;
    }
    const r = denA && denB ? num / Math.sqrt(denA * denB) : 0;
    const samples = a.map((v, i) => ({ a: v, b: b[i] }));
    msg._result = { ok: true, data: { metricA, metricB, pearson_r: Math.round(r * 1000) / 1000, sample_count: a.length, samples } };
    return msg;
}

if (action === 'analytics.anomalies') {
    const metric = payload.metric || 'meter.power_kw';
    const range = Number(payload.range) || 24;
    const series = sample(metric.startsWith('pv') ? pvAt : loadAt, range);
    const values = series.map(s => s.value);
    const mu = values.reduce((s, v) => s + v, 0) / values.length;
    const sd = Math.sqrt(values.map(v => (v - mu) ** 2).reduce((s, v) => s + v, 0) / values.length);
    const flagged = series.filter((s) => sd > 0 && Math.abs((s.value - mu) / sd) > 2);
    msg._result = { ok: true, data: { metric, range, mean: mu, stddev: sd, flagged, count: flagged.length } };
    return msg;
}

if (action === 'analytics.recommendations') {
